UPDATE public.blogs SET content = replace(content, $o$<p>Ako želite sačuvati i više od svijeće, fotografije, životnu priču i poruke bližnjih, to možete na jednom mjestu u <a href="/digitalni-memorijal" data-cta="aranzmani_memorijal">digitalnom memorijalu</a>.</p>$o$, $n$<!--widget:memorial|Kad ne možete doći do groba|Zapalite svijeću i sačuvajte fotografije, životnu priču i poruke bližnjih na jednom mjestu, gdje god živjeli.|Izradite digitalni memorijal-->$n$) WHERE slug = 'aranzmani-za-groblje' AND content NOT LIKE $l$%zradite digitalni memorijal-->%$l$;
UPDATE public.blogs SET content = replace(content, $o$<p>Mnoge obitelji nakon sprovoda objave i <a href="/objavi-osmrtnicu">zahvalu</a>, kojom se jednom porukom zahvaljuju svima koji su bili uz njih.</p>$o$, $n$<p>Mnoge obitelji nakon sprovoda objave i <a href="/objavi-osmrtnicu">zahvalu</a>, kojom se jednom porukom zahvaljuju svima koji su bili uz njih.</p><!--widget:guide-->$n$) WHERE slug = 'iskrena-sucut-tekstovi-poruke' AND content NOT LIKE $l$%z njih.</p><!--widget:guide-->%$l$;
UPDATE public.blogs SET content = replace(content, $o$<p>Ako ne možete doći na sprovod ili niste sigurni kako se javiti obitelji, sućut možete izraziti na osmrtnici. Na osmrtnica.com.hr pronađite osmrtnicu, <a href="/zapali-svijecu" data-cta="sucut_svijeca">zapalite svijeću</a> i ostavite nekoliko riječi. Obitelj će vidjeti tko je mislio na njih.</p>$o$, $n$<p>Ako ne možete doći na sprovod ili niste sigurni kako se javiti obitelji, sućut možete izraziti na osmrtnici. Na osmrtnica.com.hr pronađite osmrtnicu, <a href="/zapali-svijecu" data-cta="sucut_svijeca">zapalite svijeću</a> i ostavite nekoliko riječi. Obitelj će vidjeti tko je mislio na njih.</p><!--widget:memorial|Sjećanja koja ne nestaju|U digitalni memorijal obitelj i prijatelji mogu dodati fotografije, priče i poruke, i sve ostaje sačuvano.|Izradite digitalni memorijal-->$n$) WHERE slug = 'iskrena-sucut-tekstovi-poruke' AND content NOT LIKE $l$%zradite digitalni memorijal-->%$l$;
UPDATE public.blogs SET content = replace(content, $o$<p>Sve korake, popis dokumenata i primjere izračuna složili smo i u <a href="/besplatni-vodic/obiteljska-mirovina" data-cta="guide_link">besplatni vodič „Obiteljska mirovina korak po korak”</a>, koji možete preuzeti i ispisati.</p>$o$, $n$<!--widget:guide-->$n$) WHERE slug = 'nasljedivanje-mirovine-od-supruga' AND content NOT LIKE $l$%<!--widget:guide-->%$l$;
UPDATE public.blogs SET content = replace(content, $o$<p>Ako ste nakon smrti bližnjega naišli na ugovor za koji niste znali, prvo pribavite njegovu ovjerenu kopiju od suda ili javnog bilježnika koji ga je ovjerio.</p>$o$, $n$<p>Ako ste nakon smrti bližnjega naišli na ugovor za koji niste znali, prvo pribavite njegovu ovjerenu kopiju od suda ili javnog bilježnika koji ga je ovjerio.</p><!--widget:guide-->$n$) WHERE slug = 'ugovor-o-dozivotnom-uzdrzavanju' AND content NOT LIKE $l$%vjerio.</p><!--widget:guide-->%$l$;
